import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
assert.equal(process.platform, "linux");
const root = fileURLToPath(new URL("../", import.meta.url)), checkpointPath = path.join(root, ".work/rrsi-witness-state-source-checkpoint.json");
const checkpoint = JSON.parse(fs.readFileSync(checkpointPath, "utf8")), isolated = path.join(root, checkpoint.worktree);
const sha = (bytes) => createHash("sha256").update(bytes).digest("hex");
const check = () => { for (const item of checkpoint.sourceDigests)
  assert.equal(sha(fs.readFileSync(path.join(isolated, item.path))), item.sha256, item.path); };
check();
const helper = path.join(isolated, "packages/cli/__tests__/fixtures/rrsi-witness-state-process.mjs"), temp = fs.realpathSync.native(os.tmpdir());
const wsl1 = /^4\.4\..*-microsoft$/i.test(os.release()), results = [];
for (const kind of ["head", "segment"]) for (const mode of ["read", "fifo", "symlink", "directory", "directory-mode", "prepare-mode", "prepare-swap"]) {
  const directory = fs.mkdtempSync(path.join(temp, "cc-witness-state-process-")), start = Date.now();
  try {
    const response = spawnSync(process.execPath, [helper, directory, kind, mode], { encoding: "utf8", timeout: 15000, windowsHide: true });
    assert.equal(response.error, undefined, "child must finish before the original watchdog");
    const successful = ["read", "prepare-mode"].includes(mode);
    assert.equal(response.status, successful ? 0 : 2, response.stderr);
    const value = JSON.parse(successful ? response.stdout : response.stderr), label = kind === "head" ? "witness" : "witness segment";
    assert.equal(value.kind, kind); assert.equal(value.mode, mode); assert.equal(value.inspectionError, undefined);
    assert.equal(value.rawReads, 0); assert.equal(value.liveDescriptors, 0);
    assert.equal(value.preservedDigest, value.originalDigest); assert.equal(value.preservedLeafInode, value.originalLeafInode);
    assert.equal(value.requestsWithinChunk, true);
    const nativeDenial = mode === "directory" && wsl1;
    const endingCheck = mode === "directory-mode" || (mode === "directory" && !nativeDenial);
    if (successful) {
      assert.equal(value.payloadMatched, true); assert.equal(value.opens, 1);
      assert.equal(value.actualReadBytes, value.expectedSize);
      assert.deepEqual(value.eofProbe, { requested: 1, count: 0, position: value.expectedSize });
      assert.equal(value.fullPhysicalStorageGraphVerified, false); assert.equal(value.grantsMutationOrPromotionAuthority, false);
      assert.equal(value.fired, false);
    } else {
      assert.equal(value.code, "CC_EVOLUTION_WITNESS_STATE_READ_FAILED"); assert.equal(value.fired, true);
      const message = mode === "fifo" || mode === "symlink" ? `${label} file identity is invalid`
        : mode === "prepare-swap" ? `${label} file changed during private-file preparation`
        : mode === "directory-mode" ? `${label} directory permissions are invalid`
        : nativeDenial ? `${label} bounded read failed` : `${label} directory physical identity changed`;
      assert.equal(value.message, message); assert.equal(value.causeCode, nativeDenial ? "EACCES" : undefined);
      assert.equal(value.opens, mode === "symlink" || mode === "prepare-swap" ? 0 : 1);
      assert.equal(value.actualReadBytes, mode.startsWith("directory") ? value.expectedSize : 0);
    }
    if (mode === "fifo") assert.equal(value.actualFifo, true);
    if (mode === "symlink") assert.equal(value.actualDanglingSymlink, true);
    assert.equal(value.directoryMoved, mode === "directory" && !nativeDenial);
    assert.equal(value.directoryCopied, mode === "directory" && !nativeDenial);
    assert.equal(value.directoryModeChanged, mode === "directory-mode");
    if (!value.directoryMoved) assert.equal(value.currentDirectoryInode, value.originalDirectoryInode);
    else assert.notEqual(value.currentDirectoryInode, value.originalDirectoryInode);
    assert.equal(value.currentDirectoryMode, mode === "directory-mode" ? 0o710 : 0o700);
    const target = kind === "head" ? path.join(directory, "witness", "checkpoint.json")
      : path.join(directory, "witness", "checkpoint.json.segments-v2", fs.readdirSync(path.join(directory, "witness", "checkpoint.json.segments-v2"))[0]);
    if (mode === "directory-mode") {
      fs.chmodSync(path.dirname(target), 0o700);
      assert.equal(fs.statSync(path.dirname(target)).mode & 0o777, 0o700);
    }
    if (mode === "prepare-mode") assert.equal(value.leafMode, 0o600);
    if (mode === "prepare-swap") {
      assert.equal(value.leafMode, 0o600);
      assert.notEqual(fs.lstatSync(target, { bigint: true }).ino.toString(), value.originalLeafInode);
    }
    results.push({ kind, mode, status: "passed", durationMs: Date.now() - start, childWatchdogMs: 15000,
      childTimedOut: false, ...value, nativeRenameDenied: nativeDenial, endingDirectoryCheckVerified: endingCheck });
  } finally {
    const target = path.resolve(directory);
    assert.equal(path.dirname(target), temp); assert.ok(path.basename(target).startsWith("cc-witness-state-process-"));
    fs.rmSync(target, { recursive: true, force: true });
  }
}
check();
const report = { schema: "chainlesschain.rrsi-witness-state-posix-probes/v1", recordedAt: new Date().toISOString(),
  platform: process.platform, osRelease: os.release(), wsl1, nodeVersion: process.version, uvVersion: process.versions.uv,
  nodeBinarySha256: sha(fs.readFileSync(process.execPath)), runnerSha256: sha(fs.readFileSync(fileURLToPath(import.meta.url))),
  sourceCheckpointSha256: sha(fs.readFileSync(checkpointPath)), sourceDigests: checkpoint.sourceDigests,
  scope: "Actual local signed witness head/segment probes; WSL1 native EACCES is distinct from ending-directory coverage; not a complete Linux/macOS/release matrix",
  passedScenarios: results.length, failures: 0, results };
fs.writeFileSync(path.join(root, ".work/rrsi-witness-state-posix.json"), JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify({ passedScenarios: results.length, failures: 0, results: results.map(({ kind, mode, status, message, actualReadBytes, opens, nativeRenameDenied, endingDirectoryCheckVerified }) =>
  ({ kind, mode, status, message, actualReadBytes, opens, nativeRenameDenied, endingDirectoryCheckVerified })) }));
